import React,{useEffect,useMemo,useState} from 'react';
import { marketAPI, inventoryAPI } from '../services/api';
import { useAuth } from '../context/AuthContext';
import ImageWithFallback from '../components/ImageWithFallback';
import { resolveItemImage } from '../utils/itemAssets';
import './MarketPage.css';

const CLASSES=['Toutes','Assault Rifles','SMGs','Snipers','Pistols','Knives','Gloves'];
export default function MarketPage(){
 const {balance,updateBalance}=useAuth();
 const [listings,setListings]=useState([]),[inventory,setInventory]=useState([]),[search,setSearch]=useState(''),[weaponClass,setWeaponClass]=useState('Toutes'),[sort,setSort]=useState('newest'),[loading,setLoading]=useState(true),[busy,setBusy]=useState(null),[notice,setNotice]=useState('');
 const load=async()=>{setLoading(true);try{const [m,i]=await Promise.all([marketAPI.getListings({search,weapon_class:weaponClass==='Toutes'?'':weaponClass,sort}),inventoryAPI.getInventory()]);setListings(m.data||[]);setInventory(i.data||[])}catch(e){setNotice(e.response?.data?.detail||'Marché indisponible.')}finally{setLoading(false)}};
 useEffect(()=>{const t=setTimeout(load,180);return()=>clearTimeout(t)},[search,weaponClass,sort]);
 const [prices,setPrices]=useState({});
 const sellable=useMemo(()=>inventory.filter(x=>Number(x.quantity)>0),[inventory]);
 const buy=async row=>{if(busy)return;setBusy(row.id);setNotice('');try{const r=await marketAPI.buy(row.id);setListings(x=>x.filter(l=>l.id!==row.id));await updateBalance(r.data.balance_after);const inv=await inventoryAPI.getInventory();setInventory(inv.data||[]);setNotice(`Achat effectué : ${row.item.name} pour ${Number(row.price).toLocaleString('fr-FR')} €.`)}catch(e){setNotice(e.response?.data?.detail||'Achat impossible.')}finally{setBusy(null)}};
 const cancel=async row=>{if(busy)return;setBusy(`c${row.id}`);setNotice('');try{await marketAPI.cancel(row.id);const [m,i]=await Promise.all([marketAPI.getListings({search,weapon_class:weaponClass==='Toutes'?'':weaponClass,sort}),inventoryAPI.getInventory()]);setListings(m.data||[]);setInventory(i.data||[]);setNotice('Annonce retirée et skin rendue à ton inventaire.')}catch(e){setNotice(e.response?.data?.detail||'Impossible de retirer l’annonce.')}finally{setBusy(null)}};
 const sell=async row=>{const price=Number(prices[row.id]);if(!Number.isFinite(price)||price<=0){setNotice('Choisis un prix de vente valide.');return}setBusy(`s${row.id}`);setNotice('');try{const created=await marketAPI.createListing(row.id,price);if(created?.data){setListings(prev=>[created.data,...prev.filter(x=>x.id!==created.data.id)]);}setPrices(p=>({...p,[row.id]:''}));setNotice(`${row.item.name} est maintenant en vente à ${price.toLocaleString('fr-FR')} €.`);try{const inv=await inventoryAPI.getInventory();setInventory(inv.data||[]);}catch(refreshError){/* la publication est déjà confirmée côté serveur */}}catch(e){setNotice(e.response?.data?.detail||'Impossible de publier l’annonce.')}finally{setBusy(null)}};
 return <div className="container market-page"><section className="market-hero"><div><span className="section-kicker">WELLCASE / PLAYER MARKET</span><h1>Le <em>marché.</em></h1><p>Achète les skins des autres joueurs ou fixe ton propre prix. Le marché devient ton troisième terrain de jeu.</p></div><div className="market-wallet"><span>TON CASH</span><strong>{Number(balance||0).toLocaleString('fr-FR')} €</strong><small>Ventes entre joueurs · prix libres</small></div></section>
 {notice&&<div className="inline-notice">{notice}<button onClick={()=>setNotice('')}>×</button></div>}
 <section className="market-layout"><div className="market-main"><div className="market-toolbar"><div className="market-search">⌕<input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Chercher un skin..."/></div><select value={weaponClass} onChange={e=>setWeaponClass(e.target.value)}>{CLASSES.map(x=><option key={x}>{x}</option>)}</select><select value={sort} onChange={e=>setSort(e.target.value)}><option value="newest">Plus récentes</option><option value="price_asc">Prix croissant</option><option value="price_desc">Prix décroissant</option></select></div><div className="market-grid">{loading?<div className="market-empty">Chargement du marché…</div>:listings.length?listings.map(row=><article className="market-card" key={row.id}><div className="market-art"><ImageWithFallback src={resolveItemImage(row.item)} alt={row.item.name}/><span>{row.item.rarity}</span></div><div className="market-card-copy"><small>{row.item.weapon_class||row.item.category}</small><h3>{row.item.name}</h3><div className="market-price"><strong>{Number(row.price).toLocaleString('fr-FR')} €</strong><span>{row.condition||'État moyen'} · vendeur · {row.seller_username}</span></div>{row.is_mine?<button className="market-cancel-btn" disabled={busy===`c${row.id}`} onClick={()=>cancel(row)}>{busy===`c${row.id}`?'RETRAIT…':'RETIRER L’ANNONCE'}</button>:<button disabled={busy===row.id} onClick={()=>buy(row)}>{busy===row.id?'ACHAT…':'ACHETER'}</button>}</div></article>):<div className="market-empty"><strong>Le marché est calme.</strong><span>Sois le premier à mettre une skin en vente.</span></div>}</div></div>
 <aside className="market-sell"><div className="section-kicker">TON STOCK</div><h2>Mettre en vente</h2><p>Choisis une skin et fixe librement son prix. L’unité est retirée de ton inventaire pendant la vente.</p>{sellable.length?sellable.map(row=><div className="sell-row" key={row.id}><ImageWithFallback src={resolveItemImage(row.item)} alt=""/><div><strong>{row.item.name}</strong><small>x{row.quantity} · {row.condition||'État moyen'} · valeur {Number(row.effective_value||row.item.virtual_value).toLocaleString('fr-FR')} €</small><input type="number" min="1" step="0.01" placeholder="Prix €" value={prices[row.id]||''} onChange={e=>setPrices(p=>({...p,[row.id]:e.target.value}))}/></div><button disabled={busy===`s${row.id}`} onClick={()=>sell(row)}>{busy===`s${row.id}`?'…':'VENDRE'}</button></div>):<div className="sell-empty">Ton inventaire est vide.</div>}</aside></section></div>
}
